dw:transform-message.dw:set-payload:
var input_map = {};
var output_map = {};
var message_string = payload;
input_map = parse_hl7(message_string);
output_map = {};
var skip = false;
if (input_map.MSA) {
  var msa3_text_message = input_map.MSA[2];
  if (msa3_text_message == 'ZZZ') {
    skip = true;
  }
  if (!skip) {
    output_map.MSH = input_map.MSH;
    output_map.MSA = input_map.MSA;
  }
} else {
  return "";
}
if (skip) {
  output_map = {};
}
var json_output = write(output_map, "application/json");
input_map = {};
output_map = {};
return json_output;
